document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".case-study-showcase-section__item");if(!e.length)return;if(window.matchMedia("(prefers-reduced-motion: reduce)").matches||"undefined"==typeof IntersectionObserver)return void e.forEach(e=>e.classList.add("is-visible"));const t=new IntersectionObserver(e=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))})},{threshold:.15});e.forEach((e,s)=>{e.style.transitionDelay=s%2*100+"ms",t.observe(e)})});